SELECT product_id, quantity_bucket, avg_unit_price FROM (SELECT product_id, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items GROUP BY product_id, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) AS x WHERE avg_unit_price < 51 ORDER BY avg_unit_price DESC, product_id DESC;
